import{_ as s,o as a,c as t,ao as n}from"./chunks/framework.DSlTPKvO.js";const k=JSON.parse('{"title":"Show a scene in a notebook cell","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/slate-cell.md","filePath":"how-to/slate-cell.md","lastUpdated":null}'),i={name:"how-to/slate-cell.md"};function r(o,e,l,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="Show-a-scene-in-a-notebook-cell" tabindex="-1">Show a scene in a notebook cell <a class="header-anchor" href="#Show-a-scene-in-a-notebook-cell" aria-label="Permalink to &quot;Show a scene in a notebook cell {#Show-a-scene-in-a-notebook-cell}&quot;">​</a></h1><p>A <a href="https://github.com/kahliburke/KaimonSlate.jl" target="_blank" rel="noreferrer">KaimonSlate</a> notebook page already holds one WebSocket open. A cell that gives back a <code>Server</code> draws the scene on that socket, so <strong>a scene on a remote notebook worker needs no forwarded port</strong>. The cell shows the same viewer a browser gets.</p><h2 id="1.-Show-the-server" tabindex="-1">1. Show the server <a class="header-anchor" href="#1.-Show-the-server" aria-label="Permalink to &quot;1. Show the server {#1.-Show-the-server}&quot;">​</a></h2><p>Write the scene as usual, and put the server last in the cell:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CesiumLink</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">register_module!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(server, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">vendored</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:primitives</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server</span></span></code></pre></div><p>Slate puts <code>SlateExtensionsBase</code> on every notebook worker, so <code>using CesiumLink</code> alone loads the part of the package that draws in a cell. There is no other import and no boot cell.</p><p>Push windows from that cell, or from any cell after it. The server sends each frame down the socket of the page.</p><p><strong>The server opens no port.</strong> A cell needs none, so a port here serves nobody and is one more thing to stop. <a href="/CesiumLink.jl/stable/reference/server#CesiumLink.viewer_url"><code>viewer_url</code></a> and <a href="/CesiumLink.jl/stable/reference/server#CesiumLink.bound_port"><code>bound_port</code></a> throw, and no VSCode tab is asked for.</p><p>Ask for the port to get a page a browser can open as well:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; listen </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="2.-One-cell-draws-one-server" tabindex="-1">2. One cell draws one server <a class="header-anchor" href="#2.-One-cell-draws-one-server" aria-label="Permalink to &quot;2. One cell draws one server {#2.-One-cell-draws-one-server}&quot;">​</a></h2><p>Show one server in one cell. A second cell that shows the same server gives a line of text and no viewer. That line names the cell which holds the server.</p><p>Slate keeps one handler for each channel. A second viewer on the channel of a server takes the frames from the first viewer, and the first cell then stops with no message. The refusal makes that visible.</p><p>Two views of one scene are two servers:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># in another cell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">other </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> start_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">install_scene!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(other, my_scene)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">other</span></span></code></pre></div><p>A cell that only pushes to a server needs no viewer of its own. Do not put the server last in it.</p><h2 id="3.-What-a-re-run-does" tabindex="-1">3. What a re-run does <a class="header-anchor" href="#3.-What-a-re-run-does" aria-label="Permalink to &quot;3. What a re-run does {#3.-What-a-re-run-does}&quot;">​</a></h2><p>The teardown of the cell is the teardown of the viewer. It runs before the cell evaluates again, when you delete the cell, and before Slate rebuilds the namespace. Each time, the client leaves the server and the channel is free again.</p><p><strong>Close the viewer and the server keeps serving.</strong> The teardown drops the viewer and nothing else. The scene belongs to your worker, and <a href="/CesiumLink.jl/stable/reference/server#CesiumLink.stop_server"><code>stop_server</code></a> stops it.</p><p><strong>A browser reload keeps the scene.</strong> Slate sends the output of the cell to the page again. The viewer starts again, asks the server what the session declares, and catches up on the same path as a client that connects in mid-session.</p><p><strong>A worker that restarts needs one re-run.</strong> A new worker marks every cell stale. Run the cell again, and it mounts the viewer again.</p><h2 id="When-nothing-appears" tabindex="-1">When nothing appears <a class="header-anchor" href="#When-nothing-appears" aria-label="Permalink to &quot;When nothing appears {#When-nothing-appears}&quot;">​</a></h2><p><strong>A line of text, which names another cell.</strong> That cell holds this server. Read section 2.</p><p><strong>The text form of the server.</strong> The evaluation ran outside a cell, so the render reached no page. A URL beside it opens the scene in a browser. The words <code>(not listening)</code> instead mean the server has no port. Start it again with <code>listen = true</code>, or run the cell that draws it.</p><p><strong>An empty box.</strong> The cell mounts the built viewer. An installed package downloads that build once, as a Julia artifact. In a clone of this repository, run <code>npm run build</code> in <code>lib/</code>.</p><h2 id="Next" tabindex="-1">Next <a class="header-anchor" href="#Next" aria-label="Permalink to &quot;Next {#Next}&quot;">​</a></h2><ul><li><p><a href="https://github.com/JuliaSatcomFramework/CesiumLink.jl/blob/main/examples/Constellation/notebook.jl" target="_blank" rel="noreferrer"><code>examples/Constellation/notebook.jl</code></a> runs the Constellation example in one cell. It is this page as a notebook.</p></li><li><p><a href="/CesiumLink.jl/stable/reference/server#CesiumLink.start_server"><code>start_server</code></a> and <a href="/CesiumLink.jl/stable/reference/server#CesiumLink.viewer_url"><code>viewer_url</code></a> for the whole surface.</p></li><li><p><a href="./vscode-tab">Show a scene in a VSCode tab</a> for the same scene in an editor panel.</p></li></ul>`,27)])])}const u=s(i,[["render",r]]);export{k as __pageData,u as default};
